  expect(estimatePosition(base, 1_000_000_000n)).toBeCloseTo(11);
  // non-zero receivedAtNs + playRate != 1 pins delta-time and the rate factor.
  expect(estimatePosition({ ...base, receivedAtNs: 2_000_000_000n, playRate: 1.5 }, 3_000_000_000n)).toBeCloseTo(11.5);
});

it("weights silence when no track", () => {
  expect(audibleWeight(base)).toBe(0);
  // with a track: channel 0.8 * crossfader 0.5 = 0.4, then master bonus.
  expect(audibleWeight({ ...base, track }, { masterBonus: 0 })).toBeCloseTo(0.4, 6);
  expect(audibleWeight({ ...base, track }, { masterBonus: 0.1 })).toBeCloseTo(0.44, 6);
});

